/* AROZ R2 – detail craft / accessibility; scoped additions only. */
html { scroll-padding-top: 90px; }
:where(h1,h2,h3) { text-wrap: balance; }
:where(p,li,dd) { overflow-wrap: break-word; }
:where(a, button, input, select, textarea):focus-visible { outline: 2px solid #ff4164; outline-offset: 4px; box-shadow: 0 0 0 2px rgba(0,0,0,.5); }
:where(button, input, textarea, select) { font: inherit; }
:where(img) { max-width:100%; }
@media(prefers-reduced-motion:reduce){ html{scroll-behavior:auto!important} *,*::before,*::after{animation-duration:.01ms!important;transition-duration:.01ms!important;scroll-behavior:auto!important} }
@media(max-width:620px){
 :where(h1,h2,h3) { hyphens:auto; overflow-wrap:normal; }
 :where(p) { line-height:1.55; }
 :where(a,button) { -webkit-tap-highlight-color:transparent; }
}

