 .case{position:relative!important;inset:auto!important;opacity:1!important;visibility:visible!important;pointer-events:auto!important;display:grid!important;grid-template-columns:minmax(0,1fr)!important;grid-template-rows:auto auto!important;min-height:0!important;border-bottom:1px solid rgba(255,255,255,.16)}
