(()=>{const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;const btn=document.querySelector('.menu-btn'),menu=document.querySelector('.mobile-menu');if(btn&&menu){btn.addEventListener('click',()=>{const open=btn.getAttribute('aria-expanded')==='true';btn.setAttribute('aria-expanded',String(!open));menu.classList.toggle('open',!open);menu.setAttribute('aria-hidden',String(open));document.body.classList.toggle('menu-open',!open);if(!open)setTimeout(()=>menu.querySelector('a')?.focus(),30)});addEventListener('keydown',e=>{if(e.key==='Escape'&&menu.classList.contains('open')){btn.click();btn.focus()}})}
const previews=[...document.querySelectorAll('.live-preview')];previews.forEach(preview=>{const shot=preview.querySelector('.site-shot'),media=preview.closest('.case-media');if(!shot||!media)return;let started=false;const load=()=>{if(started||innerWidth<=1000)return;started=true;const url=shot.dataset.src;if(url)shot.src=url;};media.addEventListener('mouseenter',load,{once:true});media.addEventListener('focusin',load,{once:true});shot.addEventListener('load',()=>{if(shot.dataset.src&&shot.src===shot.dataset.src)preview.classList.add('loaded')});});
